// Generates src/design/tokens.css and src/design/tokens.ts from the single
// source of truth, ../replica/design/tokens.json. replica-brand edits only the
// JSON; run `npm run tokens` afterwards. `--check` fails (exit 1) when the
// generated files are stale, so `npm run build` can never ship old tokens.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const source = resolve(here, '../../replica/design/tokens.json')
const cssOut = resolve(here, '../src/design/tokens.css')
const tsOut = resolve(here, '../src/design/tokens.ts')

const tokens = JSON.parse(readFileSync(source, 'utf8'))
const banner = 'GENERATED by scripts/gen-tokens.mjs from replica/design/tokens.json. Do not edit by hand.'

const kebab = (s) => String(s).replace(/[^a-zA-Z0-9]+/g, '-')

function css() {
  const lines = [`/* ${banner} */`, ':root {']
  for (const [name, value] of Object.entries(tokens.color)) lines.push(`  --color-${kebab(name)}: ${value};`)
  for (const [name, value] of Object.entries(tokens.font)) lines.push(`  --font-${kebab(name)}: ${value};`)
  for (const [name, t] of Object.entries(tokens.type)) {
    lines.push(`  --text-${kebab(name)}-size: ${t.size}px;`)
    lines.push(`  --text-${kebab(name)}-line: ${t.line}px;`)
    lines.push(`  --text-${kebab(name)}-weight: ${t.weight};`)
  }
  tokens.space.forEach((v, i) => lines.push(`  --space-${i}: ${v}px;`))
  for (const [name, value] of Object.entries(tokens.radius)) lines.push(`  --radius-${kebab(name)}: ${value}px;`)
  for (const [name, value] of Object.entries(tokens.shadow)) lines.push(`  --shadow-${kebab(name)}: ${value};`)
  for (const [name, value] of Object.entries(tokens.motion)) lines.push(`  --motion-${kebab(name)}: ${value};`)
  for (const [name, value] of Object.entries(tokens.layout)) lines.push(`  --layout-${kebab(name)}: ${value}px;`)
  lines.push('}', '')
  return lines.join('\n')
}

function ts() {
  const data = {
    color: tokens.color,
    type: tokens.type,
    space: tokens.space,
    radius: tokens.radius,
    motion: tokens.motion,
    layout: tokens.layout,
  }
  return [
    `// ${banner}`,
    '// For code that cannot read CSS variables (canvas/WebGL compositor, timeline drawing).',
    `export const tokens = ${JSON.stringify(data, null, 2)} as const`,
    '',
    'export type ColorRole = keyof typeof tokens.color',
    'export type TypeStep = keyof typeof tokens.type',
    '',
  ].join('\n')
}

const outputs = [
  [cssOut, css()],
  [tsOut, ts()],
]

if (process.argv.includes('--check')) {
  const stale = outputs.filter(([path, content]) => {
    try {
      return readFileSync(path, 'utf8') !== content
    } catch {
      return true
    }
  })
  if (stale.length) {
    console.error(`tokens: stale ${stale.map(([p]) => p).join(', ')}. Run: npm run tokens`)
    process.exit(1)
  }
  console.log('tokens: up to date')
} else {
  for (const [path, content] of outputs) writeFileSync(path, content)
  console.log(`tokens: wrote ${outputs.map(([p]) => p).join(', ')}`)
}
